// Zero-Trust Hardening: Reject any non-localhost / non-127.0.0.1 ingress
const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || item;

const clientIp = headers['x-forwarded-for'] || headers['x-real-ip'] || '127.0.0.1';
const host = headers['host'] || '';
const authSecret = headers['x-nexus-auth'] || '';

const isLocalIp = clientIp.includes('127.0.0.1') || clientIp.includes('localhost') || clientIp === '::1';
const isLocalHost = host.includes('127.0.0.1') || host.includes('localhost');
const isAuthorized = authSecret === 'nexus-sre-local-token';

if (!isLocalIp || !isLocalHost || !isAuthorized) {
  throw new Error('SECURITY VIOLATION (Zero-Trust): Ingress denegado. Solicitud rechazada por no originarse estrictamente en 127.0.0.1 o carecer de token de autenticación local.');
}

return [{
  json: {
    timestamp: body.timestamp || new Date().toISOString(),
    service: body.service || 'UNKNOWN_SERVICE',
    status: body.status || 'ALERT',
    error_snippet: body.error_snippet || 'Sin logs disponibles',
    ram_available_mb: body.ram_available_mb || 0,
    load_average: body.load_average || 'N/A'
  }
}];

