const prev = $('zero-trust-sre-guard').first().json;
const aiRaw = $input.first().json;

let rcaReport = {
  rca: 'Posible saturacion transitoria o reinicio preventivo por timeout de socket',
  severity: 'MODERADA',
  action_taken: 'Reinicio automatico via PM2 / Watchdog',
  preventive_step: 'Inspeccionar consumo de memoria y sockets TCP'
};

if (aiRaw && aiRaw.response) {
  try {
    const cleaned = aiRaw.response.replace(/```json/g, '').replace(/```/g, '').trim();
    rcaReport = JSON.parse(cleaned);
  } catch (e) {}
}

return [{
  json: {
    ...prev,
    rca: rcaReport
  }
}];

